package com.wildforge.worldgen;

/**
 * Immutable parameters for the experimental terrain sampler.
 * Values are generated by ContentDataGenerator as data/wildforge/worldgen/overworld.json.
 * Changes to these values will change NEW terrain: store them (or a profile version)
 * with the world seed when chunk persistence is introduced.
 */
public record WorldGenSettings(
        int minY,
        int maxY,
        int seaLevel,
        double continentScale,
        double hillsScale,
        double mountainsScale,
        double detailScale,
        double climateScale,
        double riverScale,
        double caveScale,
        double oceanThreshold,
        double mountainThreshold,
        double caveThreshold,
        double treeDensity,
        double plantDensity) {
    public WorldGenSettings {
        if (minY >= seaLevel || seaLevel >= maxY || maxY - minY < 96) {
            throw new IllegalArgumentException("World height must leave room above and below sea level");
        }
        if (!positive(continentScale) || !positive(hillsScale)
                || !positive(mountainsScale) || !positive(detailScale)
                || !positive(climateScale) || !positive(riverScale)
                || !positive(caveScale)) {
            throw new IllegalArgumentException("World generation scales must be positive and finite");
        }
        if (!Double.isFinite(oceanThreshold) || !Double.isFinite(mountainThreshold)
                || caveThreshold <= 0 || caveThreshold >= 1
                || !Double.isFinite(caveThreshold)
                || !Double.isFinite(treeDensity) || treeDensity < 0 || treeDensity > 1
                || !Double.isFinite(plantDensity) || plantDensity < 0 || plantDensity > 1) {
            throw new IllegalArgumentException("World generation thresholds/densities invalid");
        }
    }

    private static boolean positive(double value) {
        return Double.isFinite(value) && value > 0;
    }
}
